from collections import defaultdict
class Solution:
    def getDistances(self, arr):
        g = defaultdict(list)
        for i, x in enumerate(arr):
            g[x].append(i)
        res = [0] * len(arr)
        for L in g.values():
            k = len(L)
            pre = [0] * (k + 1)
            for p in range(k):
                pre[p + 1] = pre[p] + L[p]
            for p in range(k):
                x = L[p]
                res[x] = x * p - pre[p] + (pre[k] - pre[p + 1]) - x * (k - 1 - p)
        return res

