class Solution {
public:
    vector<long long> getDistances(vector<int>& arr) {
        unordered_map<int, vector<int>> g;
        for (int i = 0; i < (int)arr.size(); i++) g[arr[i]].push_back(i);
        vector<long long> res(arr.size(), 0);
        for (auto& [v, L] : g) {
            int k = L.size();
            vector<long long> pre(k + 1, 0);
            for (int p = 0; p < k; p++) pre[p + 1] = pre[p] + L[p];
            for (int p = 0; p < k; p++) {
                long long x = L[p];
                res[x] = x * p - pre[p] + (pre[k] - pre[p + 1]) - x * (k - 1 - p);
            }
        }
        return res;
    }
};

