class Solution {
    public long[] getDistances(int[] arr) {
        Map<Integer, List<Integer>> g = new HashMap<>();
        for (int i = 0; i < arr.length; i++) g.computeIfAbsent(arr[i], z -> new ArrayList<>()).add(i);
        long[] res = new long[arr.length];
        for (List<Integer> L : g.values()) {
            int k = L.size();
            long[] pre = new long[k + 1];
            for (int p = 0; p < k; p++) pre[p + 1] = pre[p] + L.get(p);
            for (int p = 0; p < k; p++) {
                long x = L.get(p);
                res[x] = x * p - pre[p] + (pre[k] - pre[p + 1]) - x * (k - 1 - p);
            }
        }
        return res;
    }
}

