class Solution {
public:
    vector<long long> getDistances(vector<int>& arr) {
        int n = arr.size();
        vector<long long> res(n, 0);
        unordered_map<int, long long> cnt, sm;
        for (int i = 0; i < n; i++) {
            res[i] += cnt[arr[i]] * i - sm[arr[i]];
            cnt[arr[i]]++; sm[arr[i]] += i;
        }
        cnt.clear(); sm.clear();
        for (int i = n - 1; i >= 0; i--) {
            res[i] += sm[arr[i]] - cnt[arr[i]] * i;
            cnt[arr[i]]++; sm[arr[i]] += i;
        }
        return res;
    }
};

