class Solution {
    public long[] getDistances(int[] arr) {
        int n = arr.length;
        long[] res = new long[n];
        Map<Integer, Long> cnt = new HashMap<>(), sm = new HashMap<>();
        for (int i = 0; i < n; i++) {
            res[i] += cnt.getOrDefault(arr[i], 0L) * i - sm.getOrDefault(arr[i], 0L);
            cnt.merge(arr[i], 1L, Long::sum);
            sm.merge(arr[i], (long) i, Long::sum);
        }
        cnt.clear(); sm.clear();
        for (int i = n - 1; i >= 0; i--) {
            res[i] += sm.getOrDefault(arr[i], 0L) - cnt.getOrDefault(arr[i], 0L) * i;
            cnt.merge(arr[i], 1L, Long::sum);
            sm.merge(arr[i], (long) i, Long::sum);
        }
        return res;
    }
}

